var a={about:{title:"Patungkol sa mapa",hiking:"<p>Ang mapang ito ay nagpapakita ng mga ruta ng magiliw na paglalakad na mayroong nakapaskil na palatandaan sa paligid ng mundo.</p>\n",cycling:"<p>Ang mapang ito ay nagpapakita ng mga ruta ng pagbibisikleta na mayroong nakapaskil na palatandaan sa paligid ng mundo.</p>\n",mtb:"<p>Ang mapang ito ay nagpapakita ng mga ruta ng pagbibisikletang pambundok na mayroong nakapaskil na palatandaan sa paligid ng mundo.</p>\n",skating:"<p>Ang mapang ito ay nagpapakita ng mga ruta ng pag-iiskeyt na mayroong nakapaskil na palatandaan sa paligid ng mundo.</p>\n",riding:"<p>Ipinapakita ng mapa na ito ang mga naka-sign post na ruta sa pangangabayo sa iba't-ibang bahagi ng mundo.</p>\n",slopemap:"<p>Ipinapakita ng mapa na ito ang mga markadong ruta sa winter sport slopes sa iba't-ibang bahagi ng mundo.</p>\n",osm:'<p>Naka-overlay ang mga ruta sa isang standard na OpenStreetMal at pwedeng magkaroon ng layer na hillshading. Gine-generate ang mapa ng ruta nula sa data mula sa proyektong <a href="https://www.openstreetmap.org">OpenStreetMap</a> (OSM). Ang OSM ay isang mae-edit na pandaigdigang mapa kung saan pwedeng sumali ang kahit sino. Ibig sabihin, hindi ito dapat ituring na kumpleto, pero ibig sabihin din na pwede ka ring mag-ambag ng mga bagong ruta at magtama ng mga mali sa mga rutang nakalagay na rito. Para matuto pa tungkol sa OpenStreetMap, tingnan ang <a href="https://wiki.openstreetmap.org/wiki/Beginners%27_Guide">Beginner\'s guide</a>.</p>\n'},rendering:{title:"Paghaharap ng dato ng OSM",classification:"<p>Ang klasipikasyon (at kung gayon ang kulay ng ruta na nasa loob ng mapa) ay inaalam magmula sa tatak ng <code>network</code>.</p>\n",hierarchy:'<p>Tinatangkilik din ng mapa ang <a href="rendering/hierarchies">mga hirarkiya ng ugnayan</a>.</p>\n'},hierarchies:{title:"Mga hirarkiya ng ugnayan"},osmc:{title:"Ang osmc:tatak ng sagisag"},hikinglocal:{title:"Isinakatutubong paghaharap"},technical:{title:"Mga detalyeng teknikal"},acknowledgements:{title:"Mga pagkilala"},contact:{title:"Kaugnayan"}},n=a.about,g=a.rendering,i=a.hierarchies,t=a.osmc,p=a.hikinglocal,e=a.technical,o=a.acknowledgements,r=a.contact;export{n as about,o as acknowledgements,r as contact,a as default,i as hierarchies,p as hikinglocal,t as osmc,g as rendering,e as technical};
